DO $$ DECLARE f text; BEGIN SELECT pg_get_functiondef('public.admin_dashboard(text,text,integer,uuid)'::regprocedure) INTO f; f:=replace(f,'total int:=0','v_total int:=0');f:=replace(f,'INTO total','INTO v_total');f:=replace(f,'''total'',total','''total'',v_total');EXECUTE f; END $$;
CREATE TABLE public.admin_streak_resets(user_id uuid NOT NULL,season_id uuid REFERENCES public.seasons(id),day date NOT NULL,reason text NOT NULL,is_demo boolean NOT NULL DEFAULT false,PRIMARY KEY(user_id,season_id,day));
GRANT SELECT ON public.admin_streak_resets TO authenticated; GRANT ALL ON public.admin_streak_resets TO service_role;
ALTER TABLE public.admin_streak_resets ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_streak_resets ON public.admin_streak_resets FOR SELECT TO authenticated USING(user_id=auth.uid());
DO $$ DECLARE f text; BEGIN SELECT pg_get_functiondef('public.recompute_day(uuid,uuid,date)'::regprocedure) INTO f;f:=replace(f,'hp:=100*comp','IF EXISTS(SELECT 1 FROM admin_streak_resets WHERE user_id=_user_id AND season_id=_season_id AND day=d) THEN v_streak:=0; END IF;hp:=100*comp');EXECUTE f;
SELECT pg_get_functiondef('public.admin_action(text,uuid,jsonb)'::regprocedure) INTO f; f:=replace(f,'ELSE DELETE FROM checkins WHERE user_id=_target AND day=public._local_today(_target)-1; DELETE FROM day_extras WHERE user_id=_target AND day=public._local_today(_target)-1; END IF;', 'ELSE INSERT INTO admin_streak_resets(user_id,season_id,day,reason,is_demo) SELECT _target,e.season_id,public._local_today(_target),_payload->>''reason'',p.is_demo FROM season_entries e JOIN profiles p ON p.id=e.user_id WHERE e.user_id=_target ON CONFLICT(user_id,season_id,day) DO UPDATE SET reason=excluded.reason; END IF;');EXECUTE f; END $$;
CREATE FUNCTION public._require_feature(_key text) RETURNS void LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM admin_feature_flags WHERE key=_key AND NOT enabled) THEN RAISE EXCEPTION 'feature_disabled'; END IF; END $$;
REVOKE ALL ON FUNCTION public._require_feature(text) FROM PUBLIC,anon,authenticated;
DO $$ DECLARE f text; s text; k text; BEGIN FOR s,k IN SELECT * FROM(VALUES('public.buddy_action(text,uuid)','buddies'),('public.detox_duel_action(text,uuid)','duels'),('public.boss_action(uuid,text,numeric,text,text)','bosses'))v(signature,key) LOOP SELECT pg_get_functiondef(s::regprocedure) INTO f; f:=regexp_replace(f,'\mBEGIN\M','BEGIN PERFORM public._require_feature('||quote_literal(k)||');','i');EXECUTE f; END LOOP; SELECT pg_get_functiondef('public.create_challenge(text,text,integer,text,boolean,text[],boolean,boolean,boolean,date)'::regprocedure) INTO f; f:=regexp_replace(f,'\mBEGIN\M','BEGIN IF _audience=''creator'' THEN PERFORM public._require_feature(''creator_challenges''); END IF;','i');EXECUTE f; END $$;
CREATE FUNCTION public.admin_cleanup_account(_user uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE u uuid; t text; BEGIN u:=public._require_admin(); IF _user=u OR NOT EXISTS(SELECT 1 FROM profiles WHERE id=_user AND NOT is_demo AND NOT is_admin) THEN RAISE EXCEPTION 'user_protected'; END IF;
UPDATE profiles SET account_status='deleted' WHERE id=_user;
UPDATE challenges SET owner_id=u,archived=true,public_board=false WHERE owner_id=_user;
UPDATE crews SET owner_id=u,archived=true,is_public=false WHERE owner_id=_user;
DELETE FROM reports WHERE reporter=_user; DELETE FROM buddy_requests WHERE from_user=_user OR to_user=_user; DELETE FROM buddy_links WHERE from_user=_user OR to_user=_user; DELETE FROM buddy_safety_reports WHERE reporter=_user OR target=_user; DELETE FROM detox_duels WHERE a=_user OR b=_user;
DELETE FROM respects WHERE user_id=_user OR checkin_id IN(SELECT id FROM checkins WHERE user_id=_user); DELETE FROM nudges WHERE from_user=_user OR to_user=_user;
FOREACH t IN ARRAY ARRAY['announcement_receipts','creator_referrals','challenge_squad_members','bonus_points','boss_hits','boss_entries','lift_sets','screen_time_logs','detox_sessions','season_reminders','season_trophies','time_capsules','user_preferences','post_hides','post_reactions','posts','checkins','user_habits','daily_scores','day_extras','crew_members','season_entries','badges','admin_streak_resets','proof_fingerprints','activity_events','admin_suspicious_activity'] LOOP EXECUTE format('DELETE FROM public.%I WHERE user_id=$1',t) USING _user; END LOOP;
PERFORM public._admin_audit('delete_user',_user::text,'{}'); END $$;
REVOKE ALL ON FUNCTION public.admin_cleanup_account(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.admin_cleanup_account(uuid) TO authenticated;